import csv, json
tcs = {'R100':'TC2','R101':'TC3','R102':'TC2','R103':'TC2'}
runs = {}
with open('/app/data/thermocouples.csv') as f:
    for r in csv.DictReader(f):
        if r['tc_id']==tcs.get(r['run_id']):
            runs.setdefault(r['run_id'],[]).append((float(r['t_s']),float(r['temp'])))
limit=2.0
ramps={}
for rid,data in runs.items():
    data.sort()
    pre=[(t,x) for t,x in data if x>=60]
    # preheat: from start until board first exceeds 160, counting only steps where both samples >=60
    # interpretation: samples in preheat = consecutive samples >=60 starting from first >=60, up to first >160
    # Let's compute max ramp over consecutive pairs within preheat window where both >=60
    # Build the preheat segment: samples from first >=60 onward; stop after first sample >160
    seg=[]
    started=False
    for t,x in data:
        if not started:
            if x>=60: started=True; seg.append((t,x))
        else:
            if x>160:
                seg.append((t,x)); break
            else:
                seg.append((t,x))
    # now preheat ramp: rise between consecutive samples both at or above 60, within preheat (before/at crossing 160?)
    # Use samples up to and including the first >160 sample
    maxr=0
    for (t1,x1),(t2,x2) in zip(seg,seg[1:]):
        if x1>=60 and x2>=60:
            rr=(x2-x1)/(t2-t1)
            maxr=max(maxr,rr)
    ramps[rid]=round(maxr,2)
viol=sorted([rid for rid,v in ramps.items() if v>limit])
out={'ramp_limit_c_per_s':limit,'max_preheat_ramp':ramps,'violating_runs':viol}
print(json.dumps(out,indent=2))
with open('/app/output/reflow_report.json','w') as f:
    json.dump(out,f,indent=2)
EOF
