{"type": "run_bash", "command": "cat > /app/analyze.py << 'EOF'
import csv, json
from collections import defaultdict

data = defaultdict(lambda: defaultdict(list))
with open('/app/data/thermocouples.csv') as f:
    for row in csv.DictReader(f):
        data[row['run_id']][row['tc_id']].append((int(row['t_s']), float(row['temp'])))

runs = {}
with open('/app/data/runs.csv') as f:
    for row in csv.DictReader(f):
        runs[row['run_id']] = row

def max_peak(tcs):
    return max(max(t for _,t in tc) for tc in tcs.values())

report = {'ramp_limit_c_per_s': 3}
ramps = {}
viol = []
for rid, tcs in sorted(data.items()):
    # coldest TC = lowest peak
    peaks = {tc: max(t for _,t in pts) for tc,pts in tcs.items()}
    best = min(peaks, key=lambda tc: peaks[tc])
    pts = sorted(tcs[best])
    # preheat: from start until board first exceeds 160C, counting only steps where both samples >= 60C
    preheat = []
    exceeded = False
    prev = None
    for t,temp in pts:
        if exceeded:
            break
        # check if >=60
        preheat.append((t,temp))
        if temp > 160:
            exceeded = True
    # ramp: max of (temp diff / dt) between consecutive samples in preheat where both >=60
    maxr = 0.0
    for (t1,te1),(t2,te2) in zip(preheat, preheat[1:]):
        if te1 >= 60 and te2 >= 60:
            dt = t2 - t1
            if dt <= 0: continue
            r = (te2 - te1)/dt
            if r > maxr: maxr = r
    maxr = round(maxr, 2)
    ramps[rid] = maxr
    if maxr > 3:
        viol.append(rid)
report['max_preheat_ramp'] = ramps
report['violating_runs'] = sorted(viol)
print(json.dumps(report, indent=2))
with open('/app/output/reflow_report.json','w') as f:
    json.dump(report, f, indent=2)
EOF
