{"type": "run_bash", "command": "cat > /app/calc.py <<'EOF'
import csv, collections

tc = collections.defaultdict(dict)  # (run,tc) -> {t:temp}
with open('/app/data/thermocouples.csv') as f:
    for row in csv.DictReader(f):
        tc[(row['run_id'], row['tc_id'])][float(row['t_s'])] = float(row['temp'])

ref = {}
with open('/app/data/boards.csv') as f:
    for row in csv.DictReader(f):
        if row['role'] == 'reference':
            ref[row['run_id']] = row['tc_id']

runs = {}
with open('/app/data/runs.csv') as f:
    for row in csv.DictReader(f):
        runs[row['run_id']] = row

LIMIT = 2.0
results = {}
for run, tcid in sorted(ref.items()):
    d = tc.get((run, tcid))
    if not d:
        print(f"{run}: no data")
        continue
    times = sorted(d.keys())
    temps = [d[t] for t in times]
    unit = runs[run]['temp_unit']
    conv = lambda x: (x-32)*5/9 if unit=='F' else x
    ctemps = [conv(t) for t in temps]
    # preheat indices: consecutive samples both >=50, until first >150
    # find first index where temp >150
    maxramp = 0.0
    first_above150 = None
    for i in range(len(times)):
        if ctemps[i] > 150:
            first_above150 = i
            break
    end = first_above150 if first_above150 is not None else len(times)
    for i in range(1, end):
        if ctemps[i-1] >= 50 and ctemps[i] >= 50:
            dt = times[i]-times[i-1]
            if dt>0:
                r = (ctemps[i]-ctemps[i-1])/dt
                if r>maxramp: maxramp=r
    results[run] = round(maxramp,2)

viol = sorted(r for r,v in results.items() if v > LIMIT)
report = {
  "ramp_limit_c_per_s": LIMIT,
  "max_preheat_ramp": {k: results[k] for k in sorted(results)},
  "violating_runs": viol
}
import json
with open('/app/output/reflow_report.json','w') as f:
    json.dump(report, f, indent=2)
print(json.dumps(report, indent=2))
EOF
python3 /app/calc.py"}

