import csv, json
from collections import defaultdict

tc = defaultdict(list)
with open('/app/data/thermocouples.csv') as f:
    for row in csv.DictReader(f):
        tc[(row['run_id'], row['tc_id'])].append((int(row['t_s']), float(row['temp'])))

runs = {}
with open('/app/data/runs.csv') as f:
    for row in csv.DictReader(f):
        runs[row['run_id']] = row

def f2c(t):
    return (t - 32.0) * 5.0 / 9.0

def to_c(vals, unit):
    if unit == 'C':
        return [(t, v) for t, v in vals]
    elif unit == 'F':
        return [(t, f2c(v)) for t, v in vals]
    else:
        raise ValueError(unit)

def interpolate_at(vals, x):
    # vals sorted by t
    if vals[0][0] >= x:
        return vals[0][1]
    if vals[-1][0] <= x:
        return vals[-1][1]
    for (t1, v1), (t2, v2) in zip(vals, vals[1:]):
        if t1 <= x <= t2:
            if t2 == t1:
                return v1
            return v1 + (v2 - v1) * (x - t1) / (t2 - t1)

RAMP_LIMIT = 2.5
LIQ = 227.0
PEAK_MIN = 252.0
TAL_LO, TAL_HI = 30.0, 75.0
PREHEAT_END = 160.0
MIN_SAMPLE = 60.0

out_runs = {}
failing = []

for run_id in sorted(runs):
    meta = runs[run_id]
    unit = meta['temp_unit']
    # find thermocouples with data
    candidates = [(run_id, t) for (run_id_, t) in tc if run_id_ == run_id]
    # coldest = lowest peak (in C)
    best_tc = None
    best_peak = None
    for (r, t) in candidates:
        vals = to_c(tc[(r, t)], unit)
        peak = max(v for _, v in vals)
        if best_peak is None or peak < best_peak:
            best_peak = peak
            best_tc = (t, vals)
    if best_tc is None:
        # no data -> failing
        out_runs[run_id] = {"tc_id": None, "max_preheat_ramp": None, "tal_s": None, "peak_c": None, "status": "non-compliant"}
        failing.append(run_id)
        continue
    tc_id, vals = best_tc
    vals.sort(key=lambda x: x[0])

    # preheat ramp
    max_ramp = None
    for (t1, v1), (t2, v2) in zip(vals, vals[1:]):
        if t2 - t1 <= 0:
            continue
        if v1 < MIN_SAMPLE or v2 < MIN_SAMPLE:
            continue
        if v1 > PREHEAT_END:
            continue
        ramp = (v2 - v1) / (t2 - t1)
        if max_ramp is None or ramp > max_ramp:
            max_ramp = ramp

    # TAL
    start = interpolate_at(vals, LIQ)
    end = interpolate_at(vals, LIQ)
    n = len(vals)
    below = vals[:n-1]
    above = vals[1:]
    # first time below->at/above liquidus
    start_t = None
    for (t1, v1), (t2, v2) in zip(below, above):
        if v1 < LIQ and v2 >= LIQ:
            if t2 == t1:
                start_t = t1
            else:
                start_t = t1 + (LIQ - v1) / (v2 - v1) * (t2 - t1)
            break
    end_t = None
    for (t1, v1), (t2, v2) in zip(below, above):
        if v1 >= LIQ and v2 < LIQ:
            if t2 == t1:
                end_t = t1
            else:
                end_t = t1 + (LIQ - v1) / (v2 - v1) * (t2 - t1)
            break
    tal = (end_t - start_t) if (start_t is not None and end_t is not None) else 0.0

    peak_c = max(v for _, v in vals)

    compliant = True
    if max_ramp is not None and max_ramp > RAMP_LIMIT:
        compliant = False
    if not (TAL_LO <= tal <= TAL_HI):
        compliant = False
    if peak_c < PEAK_MIN:
        compliant = False

    status = "compliant" if compliant else "non-compliant"
    if not compliant:
        failing.append(run_id)

    out_runs[run_id] = {
        "tc_id": tc_id,
        "max_preheat_ramp": round(max_ramp, 2) if max_ramp is not None else None,
        "tal_s": round(tal, 2),
        "peak_c": round(peak_c, 2),
        "status": status,
    }

report = {
    "ramp_limit_c_per_s": RAMP_LIMIT,
    "runs": out_runs,
    "failing_runs": sorted(failing),
}

with open('/app/output/reflow_report.json', 'w') as f:
    json.dump(report, f, indent=2)

print(json.dumps(report, indent=2))
